{# One styled segment: bold/italic via nested tspan, color via fill #}
{% macro segout(seg) %}{% if seg.b %}{% endif %}{% if seg.i %}{% endif %}{% if seg.c %}{{ seg.t }}{% else %}{{ seg.t }}{% endif %}{% if seg.i %}{% endif %}{% if seg.b %}{% endif %}{% endmacro %}
{# One bubble line: first line flows in the text element, later lines get x/dy #}
{% macro lineout(line, first, x) %}{% if first %}{% for seg in line %}{{ segout(seg) }}{% endfor %}{% else %}{% for seg in line %}{{ segout(seg) }}{% endfor %}{% endif %}{% endmacro %}
{# A plain (legacy) line #}
{% macro plainout(line, first, x) %}{% if first %}{{ line }}{% else %}{{ line }}{% endif %}{% endmacro %}


